function bfs(nodes, edges, start){
  var adj={}; nodes.forEach(function(n){ adj[n]=[]; });
  edges.forEach(function(e){ adj[e[0]].push(e[1]); adj[e[1]].push(e[0]); });
  var visited={}, q=[start], order=[];
  visited[start]=true;
  while(q.length){ var u=q.shift(); order.push(u); adj[u].forEach(function(v){ if(!visited[v]){ visited[v]=true; q.push(v); } }); }
  return order;
}
var EXPORTS = { bfs:bfs };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
